Lemma ro_cells_CB8_C8 : forall segs m A bs,
  ro_cells segs m A [CB 8 bs] -> ro_cells segs m A [C8 (le_bytes_to_word bs)].
Proof.
  intros segs m A bs [Hwf Hb]. cbn in Hwf.
  split. { cbn. tauto. }
  cbn [cells_bytes cbytes] in *. rewrite Asn1Aux.le8_le_bytes_to_word by tauto. exact Hb.
Qed.

Ltac sig_c8 a :=
  let H := fresh "TB8" in
  tbl_cells a 8%nat as H;
  apply ro_cells_CB8_C8 in H;
  lazymatch type of H with ro_cells _ _ _ (C8 (le_bytes_to_word ?bs) :: nil) =>
    let k := eval vm_compute in (bv_unsigned (le_bytes_to_word bs)) in
    replace (le_bytes_to_word bs) with (Z_to_bv 64 k) in H by (apply bv_eq; vm_compute; reflexivity)
  end.

